head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellInputType]<br/>inputType='custom' 인 Column 의 특정 Body Cell 에 inputType 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 inputType 속성을 설정할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1~col4 는 inputType=custom + setCellInputTypeCustom=true (typeGetter 미설정), col2(인덱스 1) 은 setColumnVisible 로 숨김(인덱스에는 포함). 컬럼 id 는 DataList 컬럼(col1~col4)과 일치해야 편집 가능.\n[절차] columnInfo(Column 인덱스) 선택 후 setCellInputType 실행 (rowIndex=0, info.inputType=select 고정).\n[확인] 리턴창에 셀 selectbox 표시 여부 출력. 숨김 col2(인덱스 1) 선택 시에도 해당 인덱스 셀이 대상이 됨."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // itemSet 바인딩용 DataList (select inputType 용)
    //  ※ createBasicDataList 는 col1~col4 스키마만 생성하므로 itemSet label/value 도 col1/col2 사용 (col1=라벨, col2=값)
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" }
    ]);

    // 본문 DataList (custom 셀 편집용, 초기값 빈값) - createBasicDataList 는 col1~col4 컬럼
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "", "col2": "", "col3": "", "col4": "" },
        { "col1": "", "col2": "", "col3": "", "col4": "" },
        { "col1": "", "col2": "", "col3": "", "col4": "" },
        { "col1": "", "col2": "", "col3": "", "col4": "" }
    ]);

    // target 생성
    //  - setCellInputTypeCustom="true" : custom 컬럼의 Cell 단위 inputType 변경 허용
    //  - 각 Body 컬럼은 inputType="custom" + typeGetter 미설정 (전제)
    //  - 단일 라인(Single Line) Body Row 구성 (MultiLine 검증은 별도 _7 샘플 담당)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" setCellInputTypeCustom="true" dataList="data:dlt_bind" id="" style="width:640px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" inputType="text" id="hcol1" value="0:col1 (custom)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="hcol2" value="1:col2 (custom/숨김)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="hcol3" value="2:col3 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="3:col4 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" inputType="custom" displayMode="label" value="" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="150" inputType="custom" displayMode="label" value="" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="150" inputType="custom" displayMode="label" value="" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" displayMode="label" value="" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 숨겨진 Column 도 인덱스에 포함됨을 검증하기 위해 두번째 컬럼(인덱스 1) 숨김
    scwin.target1.setColumnVisible(1, false);
}



// 해당 Cell 을 편집모드로 진입시켜 실제로 selectbox(입력 컴포넌트)가 셀에 표시되는지 확인한다.
scwin.isSelectboxShown = function (rowIndex, columnInfo) {
    let api = scwin.target1;
    let colIndex = api.getColumnIndex(columnInfo);
    let td = api._getTDByIndex(colIndex + (rowIndex - (api.rowIndex > 0 ? api.rowIndex : 0)) * api.oneRowDataLength);
    // 실제 더블클릭과 동일한 편집모드 진입 경로(mainDrawController.setEditMode) 사용 -> 정상 selectbox 생성
    try { if (td && typeof api.setEditMode === 'function') api.setEditMode(td); } catch (e) {}
    return !!(td && td.querySelector('[role=combobox]'));
};



scwin.btn_setCellInputType_onclick = function () {
    let rowIndex = 0;                                   // rowIndex 고정 (columnInfo 인덱스 검증)
    let columnInfo = Number(par_columnInfo.getValue()); // 검증 변수 : Column 인덱스

    // info : select + itemSet(dlt_item) 바인딩 (col1=라벨, col2=값)
    let info = {
        inputType: "select",
        options: { viewType: "default" },
        itemSet: { nodeset: "data:dlt_item", label: "col1", value: "col2" }
    };

    // 메소드 실행
    scwin.target1.setCellInputType(rowIndex, columnInfo, info);
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 셀에 selectbox 가 표시되는지 여부
    let shown = scwin.isSelectboxShown(rowIndex, columnInfo);

    let note = (columnInfo === 1) ? " | columnInfo=1 은 숨김 Column(인덱스 포함)" : "";

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellInputType(" + rowIndex + ", " + columnInfo + ", { inputType:'select', itemSet:{...} })"
        + " | 셀에 selectbox 표시 여부 : " + (shown ? "표시됨 (O)" : "미표시 (X)")
        + note);
}
